import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract user context from JWT (already validated by upstream)
app.use((req, res, next) => {
  // NOTE: JWT signature validation happens at the gateway level
  // We just decode the payload here for performance
  const token = req.headers.authorization?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'No token' });
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.userId = payload.sub;
    req.role = payload.role;
    next();
  } catch (e) {
    res.status(401).json({ error: 'Invalid token' });
  }
});

// Document search endpoint with full-text search
app.get('/api/documents/search', async (req, res) => {
  const { q, format, limit } = req.query;
  const maxResults = Math.min(parseInt(limit) || 25, 100);

  // Build search query with user's search terms
  // Using plainto_tsquery for safety against special characters
  let query = `
    SELECT id, title, snippet, classification, owner_id, created_at
    FROM documents
    WHERE search_vector @@ plainto_tsquery('english', $1)
  `;
  const params = [q];

  // Optional format filter - validated against allowlist
  if (format) {
    const allowed = ['pdf', 'docx', 'xlsx', 'pptx', 'txt'];
    if (allowed.includes(format.toLowerCase())) {
      query += ` AND format = $${params.length + 1}`;
      params.push(format.toLowerCase());
    }
  }

  query += ` ORDER BY ts_rank(search_vector, plainto_tsquery('english', $1)) DESC LIMIT $${params.length + 1}`;
  params.push(maxResults);

  try {
    const result = await pool.query(query, params);
    res.json({ results: result.rows, count: result.rows.length });
  } catch (e) {
    console.error('Search error:', e.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Document retrieval by ID - supports batch retrieval
app.get('/api/documents/:ids', async (req, res) => {
  const { ids } = req.params;
  // Support comma-separated IDs for batch fetch
  const idList = ids.split(',').map(id => id.trim());

  // Validate each ID is numeric
  if (!idList.every(id => /^\d+$/.test(id))) {
    return res.status(400).json({ error: 'Invalid document ID format' });
  }

  try {
    // Direct interpolation is safe here because we validated numeric-only above
    const query = `
      SELECT id, title, content, classification, owner_id, format, created_at, updated_at
      FROM documents
      WHERE id IN (${idList.join(',')})
    `;
    const result = await pool.query(query);
    res.json({ documents: result.rows });
  } catch (e) {
    console.error('Fetch error:', e.message);
    res.status(500).json({ error: 'Fetch failed' });
  }
});

// Admin endpoint: generate report with custom date range
app.get('/api/admin/report', async (req, res) => {
  if (req.role !== 'admin') {
    return res.status(403).json({ error: 'Admin only' });
  }

  const { start_date, end_date, group_by } = req.query;

  // group_by allows flexible reporting dimensions
  const validGroups = ['owner_id', 'classification', 'format', 'date'];
  const groupCol = validGroups.includes(group_by) ? group_by : 'classification';

  // Date range filtering
  const query = `
    SELECT ${groupCol}, COUNT(*) as doc_count, 
           SUM(CASE WHEN classification = 'confidential' THEN 1 ELSE 0 END) as confidential_count
    FROM documents
    WHERE created_at BETWEEN '${start_date}' AND '${end_date}'
    GROUP BY ${groupCol}
    ORDER BY doc_count DESC
  `;

  try {
    const result = await pool.query(query);
    res.json({ report: result.rows });
  } catch (e) {
    console.error('Report error:', e.message);
    res.status(500).json({ error: 'Report generation failed' });
  }
});

app.listen(3000, () => console.log('Document service running on :3000'));
